PARAMS=['E0','Imax','IC50','ke0']
def predict(df,p):
    def solve_one(dose,ts):
        k=0.1;ke=p['ke0']
        if abs(ke-k)<1e-6: ke=k+1e-6
        Ce=dose/50*ke/(ke-k)*(np.exp(-k*ts)-np.exp(-ke*ts))
        return p['E0']-p['Imax']*Ce/(p['IC50']+Ce)
    return per_dose(df,solve_one)

